-- Batch 03: independently cross-checked public building sources. Two current evidence rows per field, one audit and one evidence group.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v5';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; sub_batch int:=3; expected_before int:=42; expected_added int:=22;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v5_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($ext$[{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"parking_above","type":"integer","value":100,"unit":"count","sources":[{"url":"https://www.donghuanguangchang.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://k.sina.com.cn/article_2664057621_9eca4b15020010mc2.html","name":"房天下商圈市场研究（新浪转载）","tier":"secondary"},{"url":"https://www.bjdch.gov.cn/ztzl/tzdc/","name":"东城区政府项目目录","tier":"primary"}],"note":"政府目录确认东中街9号、19号同一东环广场；两物业资料一致，车位为综合体共用，不是单塔；总车位为100+700。"},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"parking_underground","type":"integer","value":700,"unit":"count","sources":[{"url":"https://www.donghuanguangchang.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://k.sina.com.cn/article_2664057621_9eca4b15020010mc2.html","name":"房天下商圈市场研究（新浪转载）","tier":"secondary"},{"url":"https://www.bjdch.gov.cn/ztzl/tzdc/","name":"东城区政府项目目录","tier":"primary"}],"note":"政府目录确认东中街9号、19号同一东环广场；两物业资料一致，车位为综合体共用，不是单塔；总车位为100+700。"},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"parking_total","type":"integer","value":800,"unit":"count","sources":[{"url":"https://www.donghuanguangchang.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://k.sina.com.cn/article_2664057621_9eca4b15020010mc2.html","name":"房天下商圈市场研究（新浪转载）","tier":"secondary"},{"url":"https://www.bjdch.gov.cn/ztzl/tzdc/","name":"东城区政府项目目录","tier":"primary"}],"note":"政府目录确认东中街9号、19号同一东环广场；两物业资料一致，车位为综合体共用，不是单塔；总车位为100+700。"},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"standard_floor_area","type":"numeric","value":1000,"unit":"m2","sources":[{"url":"https://www.donghuanguangchang.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://k.sina.com.cn/article_2664057621_9eca4b15020010mc2.html","name":"房天下商圈市场研究（新浪转载）","tier":"secondary"},{"url":"https://www.bjdch.gov.cn/ztzl/tzdc/","name":"东城区政府项目目录","tier":"primary"}],"note":"政府目录确认东中街9号、19号同一东环广场；两物业资料一致，车位为综合体共用，不是单塔；总车位为100+700。"},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"floor_height","type":"numeric","value":3.8,"unit":"m","sources":[{"url":"https://www.donghuanguangchang.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://k.sina.com.cn/article_2664057621_9eca4b15020010mc2.html","name":"房天下商圈市场研究（新浪转载）","tier":"secondary"},{"url":"https://www.bjdch.gov.cn/ztzl/tzdc/","name":"东城区政府项目目录","tier":"primary"}],"note":"政府目录确认东中街9号、19号同一东环广场；两物业资料一致，车位为综合体共用，不是单塔；总车位为100+700。"},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"gfa_office","type":"numeric","value":42000,"unit":"m2","sources":[{"url":"https://www.donghuanguangchang.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://bj.bendibao.com/gouwu/2014814/160995.shtm","name":"北京本地宝项目介绍","tier":"secondary"}],"note":"两来源列写字楼部分42000多平方米；仅保留约数，不采用综合体总面积，非可租面积。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"parking_total","type":"integer","value":450,"unit":"count","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=1797&m=content","name":"人寿集团地产运营部项目资料","tier":"secondary"},{"url":"https://www.qifangfang.com/home/xiaoqu/d.html?id=2511","name":"企房房项目技术参数","tier":"secondary"}],"note":"同一CBD Z13项目；地下B2-B5共450，标准层3350平方米，货梯/消防货梯2；未把转换梯计入客梯。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"parking_underground","type":"integer","value":450,"unit":"count","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=1797&m=content","name":"人寿集团地产运营部项目资料","tier":"secondary"},{"url":"https://www.qifangfang.com/home/xiaoqu/d.html?id=2511","name":"企房房项目技术参数","tier":"secondary"}],"note":"同一CBD Z13项目；地下B2-B5共450，标准层3350平方米，货梯/消防货梯2；未把转换梯计入客梯。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"standard_floor_area","type":"numeric","value":3350,"unit":"m2","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=1797&m=content","name":"人寿集团地产运营部项目资料","tier":"secondary"},{"url":"https://www.qifangfang.com/home/xiaoqu/d.html?id=2511","name":"企房房项目技术参数","tier":"secondary"}],"note":"同一CBD Z13项目；地下B2-B5共450，标准层3350平方米，货梯/消防货梯2；未把转换梯计入客梯。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"elevator_freight","type":"integer","value":2,"unit":"count","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=1797&m=content","name":"人寿集团地产运营部项目资料","tier":"secondary"},{"url":"https://www.qifangfang.com/home/xiaoqu/d.html?id=2511","name":"企房房项目技术参数","tier":"secondary"}],"note":"同一CBD Z13项目；地下B2-B5共450，标准层3350平方米，货梯/消防货梯2；未把转换梯计入客梯。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"clear_height","type":"numeric","value":3,"unit":"m","sources":[{"url":"https://www.renshoujinrong.cn/index.html","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.qifangfang.com/home/xiaoqu/d.html?id=2511","name":"企房房项目技术参数","tier":"secondary"}],"note":"两来源净高3米及三家运营商一致；结构层高存在4.35/4.5差异故不填。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"telecom_provider","type":"text","value":"电信、联通、移动","unit":"configuration","sources":[{"url":"https://www.renshoujinrong.cn/index.html","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.qifangfang.com/home/xiaoqu/d.html?id=2511","name":"企房房项目技术参数","tier":"secondary"}],"note":"两来源净高3米及三家运营商一致；结构层高存在4.35/4.5差异故不填。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"well_certification","type":"text","value":"WELL-CS 金级（2021年已取得）","unit":"certification","sources":[{"url":"https://www.chinalifeinvest.com/invest/report/2105/0018-1.htm","name":"国寿投资2021年项目公告","tier":"primary"},{"url":"https://www.honeywell.com.cn/solutions/by-industry/buildings-cities/healthy-buildings/case-z13","name":"霍尼韦尔项目案例","tier":"primary"}],"note":"仅记录两方独立确认的历史获得金级事实，不声称当前最高等级或证书仍有效；最新等级另待独立核实。"},{"id":"ee508e17-c04a-461b-8939-dee561622447","f":"floors_above","type":"integer","value":39,"unit":"floor","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=13&id=626&m=content","name":"北京写字楼招商资讯","tier":"secondary"},{"url":"https://www.jinglou8.com/xiezilou/zhongyedasha.html","name":"京楼网中冶大厦项目参数","tier":"secondary"}],"note":"曙光西里28号，同址项目参数表一致；停车为约数；不采用同页泛化简介的其他楼层或净高。"},{"id":"ee508e17-c04a-461b-8939-dee561622447","f":"floors_below","type":"integer","value":4,"unit":"floor","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=13&id=626&m=content","name":"北京写字楼招商资讯","tier":"secondary"},{"url":"https://www.jinglou8.com/xiezilou/zhongyedasha.html","name":"京楼网中冶大厦项目参数","tier":"secondary"}],"note":"曙光西里28号，同址项目参数表一致；停车为约数；不采用同页泛化简介的其他楼层或净高。"},{"id":"ee508e17-c04a-461b-8939-dee561622447","f":"parking_total","type":"integer","value":420,"unit":"count","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=13&id=626&m=content","name":"北京写字楼招商资讯","tier":"secondary"},{"url":"https://www.jinglou8.com/xiezilou/zhongyedasha.html","name":"京楼网中冶大厦项目参数","tier":"secondary"}],"note":"曙光西里28号，同址项目参数表一致；停车为约数；不采用同页泛化简介的其他楼层或净高。"},{"id":"ee508e17-c04a-461b-8939-dee561622447","f":"efficiency_rate","type":"numeric","value":70,"unit":"percent","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=13&id=626&m=content","name":"北京写字楼招商资讯","tier":"secondary"},{"url":"https://www.jinglou8.com/xiezilou/zhongyedasha.html","name":"京楼网中冶大厦项目参数","tier":"secondary"}],"note":"曙光西里28号，同址项目参数表一致；停车为约数；不采用同页泛化简介的其他楼层或净高。"},{"id":"04533c67-3d91-435f-b0f2-6628913bfbbd","f":"floor_height","type":"numeric","value":3.3,"unit":"m","sources":[{"url":"https://www.bjzgcgjcx.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://www.xzlsd.com/m/rentfy_x.aspx?fyId=82923&proId=3821","name":"首都写字楼出租网","tier":"secondary"}],"note":"北四环西路67号同一楼宇；标准层高3.3m、得房率70%；不同资料的总面积和梯数有冲突，未使用。"},{"id":"04533c67-3d91-435f-b0f2-6628913bfbbd","f":"efficiency_rate","type":"numeric","value":70,"unit":"percent","sources":[{"url":"https://www.bjzgcgjcx.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://www.xzlsd.com/m/rentfy_x.aspx?fyId=82923&proId=3821","name":"首都写字楼出租网","tier":"secondary"}],"note":"北四环西路67号同一楼宇；标准层高3.3m、得房率70%；不同资料的总面积和梯数有冲突，未使用。"},{"id":"debe7ba6-03e3-4f9e-a95b-afdfc4a51671","f":"clear_height","type":"numeric","value":2.7,"unit":"m","sources":[{"url":"https://www.bjlzxz.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://sbzszx.com/productinfo/144547.html?templateId=1133605","name":"商办招商项目资料","tier":"secondary"}],"note":"知春路27号芯座，地下一层、装修后净高2.7m、玻璃幕墙；层高存在其他公开记录差异未填。"},{"id":"debe7ba6-03e3-4f9e-a95b-afdfc4a51671","f":"facade_type","type":"text","value":"玻璃幕墙","unit":"configuration","sources":[{"url":"https://www.bjlzxz.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://sbzszx.com/productinfo/144547.html?templateId=1133605","name":"商办招商项目资料","tier":"secondary"}],"note":"知春路27号芯座，地下一层、装修后净高2.7m、玻璃幕墙；层高存在其他公开记录差异未填。"},{"id":"debe7ba6-03e3-4f9e-a95b-afdfc4a51671","f":"floors_below","type":"integer","value":1,"unit":"floor","sources":[{"url":"https://www.bjlzxz.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://sbzszx.com/productinfo/144547.html?templateId=1133605","name":"商办招商项目资料","tier":"secondary"}],"note":"知春路27号芯座，地下一层、装修后净高2.7m、玻璃幕墙；层高存在其他公开记录差异未填。"}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text)) SELECT b.id bid,b.name,d.id target_id,v.f field_name,v.value new_value,v.type value_type,v.unit,v.sources,v.note FROM specs v JOIN building_brochure_data d ON d.id=v.id JOIN buildings b ON b.id=d.building_id WHERE b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.project_type='stock' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data q WHERE q.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND (SELECT count(distinct substring(s->>'url' from 'https?://([^/]+)')) FROM jsonb_array_elements(v.sources) s)>=2 AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=b.id AND p.target_table='building_brochure_data' AND p.field_name=v.f) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=d.id::text AND (a.details->>'field_name'=v.f OR a.new_values ? v.f)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_url,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  SELECT r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'internet',e->>'tier',e->>'name',e->>'url',now_ts,now_ts,'cross_verified',ev,'batch_ref=ai_building_field_backfill_20261125_v5_100; unit='||r.unit||'; '||r.note||'; AI-assisted',true FROM jsonb_array_elements(r.sources) e;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>jsonb_array_length(r.sources) OR changed<2 THEN RAISE EXCEPTION 'source count mismatch'; END IF;
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v5_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_kind','external_cross_verified','source_urls',r.sources,'unit',r.unit,'verification_status','cross_verified','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value)<>jsonb_array_length(r.sources) OR NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.event_id='ai_field_fill:'||ev::text AND a.new_values->r.field_name=read_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected %, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
COMMIT;